package com.bechir.shop;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.FrameLayout;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> chooser;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(getPackageName().endsWith(".pro")){if(android.os.Build.VERSION.SDK_INT>=26){android.app.NotificationManager nm=getSystemService(android.app.NotificationManager.class);nm.createNotificationChannel(new android.app.NotificationChannel("shop_orders","طلبات المتجر",android.app.NotificationManager.IMPORTANCE_HIGH));}if(android.os.Build.VERSION.SDK_INT>=33 && checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},51);}}FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff291344);web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if("tel".equals(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_DIAL,u));}catch(Exception ignored){}return true;}return !("https".equals(u.getScheme())&&"gueddich46-lab.github.io".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/BechirShop/"));}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> c,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=c;try{startActivityForResult(p.createIntent(),42);return true;}catch(Exception ex){chooser.onReceiveValue(null);chooser=null;return false;}}});web.loadUrl("https://gueddich46-lab.github.io/BechirShop/"+BuildConfig.START_PAGE);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==42&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));chooser=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}